beforeExample:
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class MyClass {
    public void process(String data) throws IOException {
        // Old way, uses platform default charset
        ByteArrayInputStream is = new ByteArrayInputStream(data.getBytes());
        is.close();
    }
}

afterExample:
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class MyClass {
    public void process(String data) throws IOException {
        // Modern way, explicitly uses UTF-8
        ByteArrayInputStream is = new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8));
        is.close();
    }
}

negativeExample:
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class MyClass {
    public void process(String data) throws IOException {
        // Already uses a specific charset (should not match)
        ByteArrayInputStream is1 = new ByteArrayInputStream(data.getBytes("ISO-8859-1"));
        ByteArrayInputStream is2 = new ByteArrayInputStream(data.getBytes(StandardCharsets.US_ASCII));

        // Not a getBytes() call (should not match)
        String s = data.trim();
    }
}
